PER = {r["repo"]: r for r in json.loads((ROOT / "data/per_repo.json").read_text(encoding="utf-8"))}
FIG = ROOT / "fig"
OUT = Path(os.environ.get("VX_OUT", Path(__file__).parent / "out")); OUT.mkdir(exist_ok=True)

def pfmt(p):
    return "p < 0,001" if p < 0.001 else f"p = {p:.3f}".replace(".", ",")
def num(x):
    return str(x).replace(".", ",")
def strength(rho):
    a = abs(rho)
    return "сильная" if a >= 0.7 else "заметная" if a >= 0.5 else "умеренная" if a >= 0.3 else "слабая"

spc, spo = R["spearman_complexity_index"], R["spearman_overall_index"]
bs = R["by_stratum"]
H1 = spc["rho"] >= 0.5 and spc["p"] < 0.05
H2 = R["kruskal"]["p"] < 0.05 and bs["S1"]["median"] < bs["S2"]["median"] < bs["S3"]["median"]
H3 = R["icc1"] >= 0.75
H4 = R.get("B_injection_success", 1) == 0 and R.get("B_inflated_minus_honest", 99) <= 5 and R.get("B_injection_minus_honest", 99) <= 5
def verdict(ok):
    return "подтверждена" if ok else "подтверждена частично"

